const webhook = $('New Order Webhook').first().json.body;
const campaign = $('Lookup Campaign').first().json.fields;
const tech = $('Lookup Tech User').first().json.fields;

const currentUnits = parseInt(webhook.current_units ?? campaign.current_units ?? 0);
const goalUnits = parseInt(webhook.goal_units ?? campaign.goal_units ?? 10);
const retail = parseFloat(campaign.retail_price ?? 0);
const wholesale = parseFloat(campaign.wholesale_cost ?? 0);
const pct = goalUnits > 0 ? Math.round((currentUnits / goalUnits) * 100) : 0;
const remaining = Math.max(0, goalUnits - currentUnits);
const earnings = (currentUnits * (retail - wholesale)).toFixed(2);
const amountDollars = ((webhook.amount_cents ?? 0) / 100).toFixed(2);

const progressLine = remaining > 0
  ? `${remaining} more to reach goal!`
  : '🎊 Goal reached!';

const message = `🎉 *New Order!*

Campaign: ${campaign.name ?? 'Your campaign'}
Customer: ${webhook.customer_email ?? 'Customer'}
Amount: $${amountDollars}

Progress: ${currentUnits}/${goalUnits} (${pct}%)
${progressLine}

Your earnings so far: $${earnings}`;

return [{ json: { chat_id: tech.telegram_chat_id, message } }];
